// RenderReport — full HTML (bagian 20)
const inc = (() => { try { return $('QIncident').first().json; } catch (e) { return null; } })();
if (!inc || !inc.incident_id) return [{ json: { html: '<h1>Incident not found</h1>', notfound: true } }];
const evts = $('QEvents').all().map(i => i.json);
const iocs = (() => { try { return $('QIOCs').all().map(i => i.json); } catch (e) { return []; } })();
const acts = (() => { try { return $('QActions').first().json; } catch (e) { return {}; } })();
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
// cloud-fidelity (repo-only, NOT live-deployed): hostname lives in raw.observables.src_host; cloud Event column shows the action name with outcome fallback.
const _src = (e) => e.src_ip || (((e.raw || {}).observables || {}).src_host || '');
const _evt = (e) => { const o = ((e.raw || {}).observables || {}); return (e.source === 'cloudtrail' && o.event_name) ? o.event_name : e.outcome; };
const erow = evts.map(e => '<tr><td>' + esc(e.ts) + '</td><td>' + esc(_src(e)) + '</td><td>' + esc(e.username) + '</td><td>' + esc(e.rule_id) + '</td><td>' + esc(_evt(e)) + '</td></tr>').join('');
const irow = iocs.map(o => '<tr><td>' + esc(o.ioc_type) + '</td><td>' + esc(o.value) + '</td></tr>').join('');
// deterministic process chain (parent -> child) from captured observables
const obs = (e) => { try { return (e.raw || {}).observables || {}; } catch (x) { return {}; } };
const procs = evts.filter(e => { const o = obs(e); return o.parent_image || o.command; });
const prow = procs.map(e => { const o = obs(e); return '<tr><td>' + esc(e.ts) + '</td><td>' + esc(o.parent_image || '-') + '</td><td>' + esc(o.command || o.url || '-') + '</td><td>' + esc((o.hash || '').slice(0, 16) + ((o.hash || '').length > 16 ? '...' : '')) + '</td></tr>'; }).join('');
const ptree = procs.length ? ('<h2>Process chain (deterministic)</h2><table border=1><tr><th>ts</th><th>parent_image</th><th>command / url</th><th>hash</th></tr>' + prow + '</table>') : '';
const html = '<html><head><title>' + esc(inc.incident_id) + '</title></head><body style="font-family:monospace">'
 + '<h1>SOC Investigation Report ' + esc(inc.incident_id) + '</h1>'
 + '<p>Status: <b>' + esc(inc.status) + '</b> | Risk: see evidence | Source: ' + esc(inc.source) + ' | Created: ' + esc(inc.created_at) + '</p>'
 + '<p>Note: ' + esc(inc.analyst_note || '-') + '</p>'
 + '<h2>AI Summary</h2><pre>' + esc(inc.ai_summary || '-') + '</pre>'
 + '<h2>Events (' + evts.length + ')</h2><table border=1><tr><th>ts</th><th>src</th><th>user</th><th>rule</th><th>outcome</th></tr>' + erow + '</table>'
 + '<h2>IOCs</h2><table border=1><tr><th>type</th><th>value</th></tr>' + irow + '</table>'
 + ptree + '<h2>Decision</h2><pre>' + esc(JSON.stringify(acts)) + '</pre>'
 + '</body></html>';
return [{ json: { html } }];

const q = ($input.first().json.query || {});
const incident_id = String(q.incident_id || '').replace(/'/g, "''");
const key = String(q.key || '').replace(/'/g, "''");
return [{ json: { incident_id, key } }];

const q = ($input.first().json.query || {});
const key = String(q.key || '').replace(/'/g, "''");
return [{ json: { key } }];

// RenderMetrics — SOC KPI dashboard (deterministic, from analyst_decisions + incidents)
const r = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const tpfp = ((r.tp || 0) + (r.fp || 0)) ? Math.round(100 * (r.tp || 0) / ((r.tp || 0) + (r.fp || 0))) : '-';
const row = (k, v) => '<tr><td>' + esc(k) + '</td><td>' + esc(v) + '</td></tr>';
let h = '<html><head><title>SOC Metrics</title></head><body style="font-family:monospace">'
 + '<h1>SOC Metrics (live)</h1>'
 + '<h2>Disposition</h2><table border=1><tr><th>metric</th><th>value</th></tr>'
 + row('incidents (total)', r.total) + row('open', r.open)
 + row('TP', r.tp) + row('FP', r.fp) + row('ESCALATE', r.esc)
 + row('TP rate (decided)', tpfp + '%') + row('analysts active', r.analysts)
 + row('MTTR proxy (h, TP/FP)', (r.mttr_h === null ? '-' : r.mttr_h)) + '</table>'
 + '<h2>Risk distribution</h2><table border=1><tr><th>level</th><th>count</th></tr>'
 + row('HIGH', r.high) + row('MEDIUM', r.med) + row('LOW', r.low) + '</table>';
try { const pd = r.per_day || []; h += '<h2>Incidents/day (14d)</h2><table border=1><tr><th>day</th><th>count</th></tr>' + pd.map(x => row(x.d, x.c)).join('') + '</table>'; } catch (e) {}
try { const tr = r.top_rules || []; h += '<h2>Top rules</h2><table border=1><tr><th>rule</th><th>count</th></tr>' + tr.map(x => row(x.r, x.c)).join('') + '</table>'; } catch (e) {}
h += '<p>Source of truth: analyst_decisions + incidents. MTTR = decision_time - incident_time.</p></body></html>';
return [{ json: { html: h } }];
